mapper.select:
SELECT eu.user_id, u.real_name, u.user_no, s.status AS sheet_status, s.submit_time, s.objective_score, s.total_score, s.is_passed, s.screen_switch_count FROM exam_user eu JOIN sys_user u ON u.id = eu.user_id AND u.deleted = 0 LEFT JOIN answer_sheet s ON s.id = ( SELECT MAX(x.id) FROM answer_sheet x WHERE x.exam_id = eu.exam_id AND x.user_id = eu.user_id AND x.status IN (2, 3, 4) ) WHERE eu.exam_id = #{examId}
AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.user_no ASC, eu.id ASC
